namespace Customize\Repository\Master;

use Doctrine\Persistence\ManagerRegistry as RegistryInterface;
use Customize\Entity\Master\ShinaiLength;
use Eccube\Repository\AbstractRepository;

/**
 * ShinaiLengthRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class ShinaiLengthRepository extends AbstractRepository
{
    public function __construct(RegistryInterface $registry)
    {
        parent::__construct($registry, ShinaiLength::class);
    }

    public function selectIdArray()
    {
        $all = $this->findAll();
        $arr = array();
        foreach ($all as $entity) {
            $arr[$entity->getId()] = $entity;
        }
        return $arr;
    }


}
